(function(){
  // The page is its own Markdown. The HTML file holds a heading and a link to
  // /garage/round-trip.md; this fetches that file, renders it with the same
  // parser the demo uses, and puts the demo under its heading. md-to-html.js
  // escapes every character of input before it reaches the DOM.
  var doc = document.getElementById("rt-doc"), demo = document.getElementById("rt-demo"), proof = document.getElementById("rt-proof");
  var out = document.getElementById("rt-out"), pick = document.getElementById("rt-page");
  if (!doc || !demo || !proof || !out || !pick || !window.fetch || !window.DOMParser) return;
  var lib = import("./md-to-html.js");
  var text = function(r){ if (!r.ok) throw new Error(r.url + " answered " + r.status); return r.text(); };
  var ORIGIN = "https://aadhar.sh";
  Promise.all([fetch("/garage/round-trip.md").then(text), lib]).then(function(got){
    var md = got[0], t0 = performance.now();
    // With its origin, the parser writes the page a hand-written Garage page
    // would be: the intro paragraph, links on this site as paths, and every
    // term in the same markup, byte for byte. A contract test holds it there.
    doc.innerHTML = got[1].mdToHtml(md, { origin: ORIGIN });
    var anchor = null;
    doc.querySelectorAll("h2").forEach(function(h){ if (!anchor && /^Take a page on the trip/.test(h.textContent)) anchor = h.nextElementSibling || h; });
    if (anchor) anchor.after(demo); else doc.after(demo);
    doc.classList.remove("rt-pending");
    demo.hidden = false;
    var ms = performance.now() - t0;
    var nav = performance.getEntriesByType && performance.getEntriesByType("navigation")[0];
    var htmlBytes = nav && nav.decodedBodySize ? nav.decodedBodySize : document.documentElement.outerHTML.length;
    doc.after(proof);
    proof.textContent = "Measured on this visit: the HTML file was " + htmlBytes.toLocaleString("en-US") +
      " bytes, the Markdown was " + new Blob([md]).size.toLocaleString("en-US") +
      " bytes, and building this page from the Markdown took " + (ms < 1 ? "under 1" : Math.round(ms)) + " ms.";
    proof.hidden = false;
    run();
  }).catch(function(e){
    doc.classList.remove("rt-pending");
    doc.innerHTML = '<h1>There and back</h1><p></p>';
    doc.querySelector("p").textContent = "This page is written in Markdown, and the Markdown did not load (" + e.message + "). It lives at /garage/round-trip.md.";
  });

  var fmt = function(n){ return n.toLocaleString("en-US") + " B"; };
  var words = function(s){ return (s.toLowerCase().match(/[a-z0-9]+/g) || []); };
  var recall = function(a, b){
    var bag = {}, hit = 0;
    b.forEach(function(w){ bag[w] = (bag[w] || 0) + 1; });
    a.forEach(function(w){ if (bag[w]) { hit++; bag[w]--; } });
    return a.length ? hit / a.length : 1;
  };
  var leg = function(n, lbl){ return '<div class="rt-leg"><span class="n">' + n + '</span><span class="lbl">' + lbl + '</span></div>'; };
  function run(){
    var path = pick.value;
    out.textContent = "fetching " + path + " and " + path + ".md";
    Promise.all([fetch(path).then(text), fetch(path + ".md").then(function(r){ return r.ok ? r.text() : ""; }), lib])
      .then(function(got){
        var html = got[0], md = got[1], rebuilt = got[2].mdToHtml(md, { origin: ORIGIN });
        if (!md) { out.textContent = path + " has no twin to rebuild"; return; }
        var page = new DOMParser().parseFromString(html, "text/html");
        // A page that renders from its own Markdown ships a frame, so its HTML
        // has no words to keep and the count would measure the frame.
        var frame = !!page.getElementById("rt-doc");
        var content = page.querySelector(".content") || page.body;
        var n = function(sel){ return content.querySelectorAll(sel).length; };
        var dropped = [["script", n("script")], ["button", n("button")], ["form control", n("input,select,textarea")], ["canvas", n("canvas")], ["svg", n("svg")]]
          .filter(function(d){ return d[1]; }).map(function(d){ return d[1] + " " + d[0] + (d[1] === 1 ? "" : "s"); });
        content.querySelectorAll("script,style,button,input,select,textarea,label,noscript,template,svg,canvas,#luq,.title-bar,.status").forEach(function(e){ e.remove(); });
        var frag = new DOMParser().parseFromString(rebuilt, "text/html").body;
        var kept = frame ? "HTML rebuilt here: all of this page's words" : "HTML rebuilt here, " + (recall(words(content.textContent), words(frag.textContent)) * 100).toFixed(1) + "% of words kept";
        out.innerHTML = '<div class="rt-legs">' +
          leg(fmt(new Blob([html]).size), frame ? "HTML as served, a frame with no page in it" : "HTML, as served") +
          leg(fmt(new Blob([md]).size), frame ? "Markdown, the source" : "Markdown twin") +
          leg(fmt(new Blob([rebuilt]).size), kept) +
          '</div><div class="rt-panes"><div><div class="rt-pane"><pre></pre></div><p class="rt-cap">the twin, as an agent reads it</p></div>' +
          '<div><div class="rt-pane prose rt-rebuilt"></div><p class="rt-cap">the twin, rebuilt as HTML</p></div></div>' +
          '<p class="rt-drop"></p>';
        out.querySelector("pre").textContent = md;
        out.querySelector(".rt-rebuilt").innerHTML = rebuilt;
        out.querySelector(".rt-drop").textContent = dropped.length
          ? "Left behind on the way down: " + dropped.join(", ") + "."
          : "Nothing interactive on this page, so nothing was left behind on the way down.";
      })
      .catch(function(e){ out.textContent = "the trip failed: " + e.message; });
  }
  pick.addEventListener("change", run);
})();
